from __future__ import annotations

"""Domain model for Assistants runs that pause for tool outputs.

When a run needs your code to do something, it moves to ``requires_action`` and
its ``required_action.submit_tool_outputs.tool_calls`` lists what to run. Your
worker executes each call, then submits one output per ``tool_call_id``. The run
only advances once. The hard part: more than one poller can observe the same run
in ``requires_action`` before any of them submits.
"""

import json
from dataclasses import dataclass, field


# Run lifecycle states we care about here.
REQUIRES_ACTION = "requires_action"
QUEUED = "queued"
IN_PROGRESS = "in_progress"
COMPLETED = "completed"
CANCELLED = "cancelled"
EXPIRED = "expired"


class ToolArgumentError(ValueError):
    """Raised when tool-call arguments are not a valid JSON object."""


@dataclass(frozen=True)
class ToolCall:
    id: str
    name: str
    arguments_json: str = "{}"

    def __post_init__(self) -> None:
        if not self.id.strip():
            raise ValueError("tool_call id is required")
        if not self.name.strip():
            raise ValueError("tool_call name is required")

    def parsed_arguments(self) -> dict:
        try:
            parsed = json.loads(self.arguments_json)
        except json.JSONDecodeError as exc:
            raise ToolArgumentError(f"call {self.id}: invalid JSON arguments") from exc
        if not isinstance(parsed, dict):
            raise ToolArgumentError(f"call {self.id}: arguments must be an object")
        return parsed

    @classmethod
    def from_raw(cls, raw: dict) -> "ToolCall":
        function = raw.get("function") or {}
        return cls(
            id=str(raw.get("id", "")).strip(),
            name=str(function.get("name", "")).strip(),
            arguments_json=function.get("arguments") or "{}",
        )


@dataclass(frozen=True)
class ToolOutput:
    tool_call_id: str
    output: str

    def to_wire(self) -> dict:
        return {"tool_call_id": self.tool_call_id, "output": self.output}


@dataclass
class Run:
    run_id: str
    status: str
    tool_calls: tuple[ToolCall, ...] = field(default_factory=tuple)
    thread_id: str = "thread_default"
    assistant_id: str = "asst_default"
    submitted_outputs: list[ToolOutput] = field(default_factory=list)
    submitted_tool_call_ids: set[str] = field(default_factory=set)

    def requires_action(self) -> bool:
        return self.status == REQUIRES_ACTION

    def required_tool_calls(self) -> list[ToolCall]:
        if not self.requires_action():
            return []
        return list(self.tool_calls)

    def tool_call_ids(self) -> list[str]:
        return [tc.id for tc in self.tool_calls]


def tool_call(call_id: str, name: str, **arguments) -> ToolCall:
    return ToolCall(id=call_id, name=name, arguments_json=json.dumps(arguments))


def build_run_requiring_action(
    run_id: str,
    tool_calls: list[ToolCall],
    thread_id: str = "thread_default",
    assistant_id: str = "asst_default",
) -> Run:
    if not tool_calls:
        raise ValueError("a requires_action run needs at least one tool call")
    return Run(
        run_id=run_id,
        status=REQUIRES_ACTION,
        tool_calls=tuple(tool_calls),
        thread_id=thread_id,
        assistant_id=assistant_id,
    )


def run_from_raw(raw: dict) -> Run:
    """Decode a run payload (as returned by the API) into a Run."""

    required_action = raw.get("required_action") or {}
    submit = required_action.get("submit_tool_outputs") or {}
    raw_calls = submit.get("tool_calls") or []
    calls = [ToolCall.from_raw(rc) for rc in raw_calls]
    return Run(
        run_id=str(raw.get("id", "")).strip(),
        status=str(raw.get("status", REQUIRES_ACTION)),
        tool_calls=tuple(calls),
        thread_id=str(raw.get("thread_id", "thread_default")),
        assistant_id=str(raw.get("assistant_id", "asst_default")),
    )


def submit_tool_outputs_payload(run: Run, outputs: list[ToolOutput]) -> dict:
    """Shape the request body the SDK would send for submitToolOutputs."""

    return {
        "run_id": run.run_id,
        "thread_id": run.thread_id,
        "tool_outputs": [o.to_wire() for o in outputs],
    }


def is_terminal_status(status: str) -> bool:
    return status in {COMPLETED, CANCELLED, EXPIRED}

