from __future__ import annotations

"""Roll up a coordinator's state for support and finance review."""

from run_coordinator import RunCoordinator


def summarize_run(coordinator: RunCoordinator, run_id: str) -> dict[str, object]:
    run = coordinator.store.get(run_id)
    return {
        "run_id": run_id,
        "status": run.status,
        "tool_call_count": len(run.tool_calls),
        "submitted_output_count": len(run.submitted_outputs),
        "transition_count": coordinator.store.transition_count(run_id),
        "real_executions": coordinator.executor.real_execution_count(),
    }


def world_snapshot(coordinator: RunCoordinator) -> dict[str, object]:
    world = coordinator.world
    return {
        "refund_total_cents": world.get("refund_total_cents", 0),
        "reserved": dict(world.get("reserved", {})),
    }


def double_charge_detected(coordinator: RunCoordinator) -> bool:
    """True if any side effect ran more than once."""

    executions = coordinator.executor.executions
    return len(executions) != len(set(executions))


def total_refunded_cents(coordinator: RunCoordinator) -> int:
    return int(coordinator.world.get("refund_total_cents", 0))


def per_tool_execution_counts(coordinator: RunCoordinator) -> dict[str, int]:
    counts: dict[str, int] = {}
    for tool_call_id in coordinator.executor.executions:
        counts[tool_call_id] = counts.get(tool_call_id, 0) + 1
    return counts


def reserved_units(coordinator: RunCoordinator) -> dict[str, int]:
    return dict(coordinator.world.get("reserved", {}))


def transition_count(coordinator: RunCoordinator, run_id: str) -> int:
    return coordinator.store.transition_count(run_id)


def summarize_all_runs(coordinator: RunCoordinator) -> list[dict[str, object]]:
    return [summarize_run(coordinator, rid) for rid in coordinator.store.all_run_ids()]


def is_run_clean(coordinator: RunCoordinator, run_id: str) -> bool:
    summary = summarize_run(coordinator, run_id)
    return (
        not double_charge_detected(coordinator)
        and summary["transition_count"] == 1
        and summary["submitted_output_count"] == summary["tool_call_count"]
    )

