from __future__ import annotations

"""Short-lived claims so two workers don't process a run at the same instant.

A claim is mutual exclusion for one processing attempt, not a durable lock: it is
released as soon as the attempt finishes. Because delivery is at-least-once, a
run can still be picked up again after a claim is released — correctness under
that comes from idempotency, not from the claim.
"""


class RunClaim:
    def __init__(self) -> None:
        self._holders: dict[str, str] = {}

    def try_claim(self, run_id: str, worker_id: str) -> bool:
        if not worker_id:
            raise ValueError("worker_id is required")
        current = self._holders.get(run_id)
        if current is not None and current != worker_id:
            return False
        self._holders[run_id] = worker_id
        return True

    def holder(self, run_id: str) -> str | None:
        return self._holders.get(run_id)

    def is_claimed(self, run_id: str) -> bool:
        return run_id in self._holders

    def release(self, run_id: str, worker_id: str) -> None:
        current = self._holders.get(run_id)
        if current is not None and current != worker_id:
            raise ValueError("cannot release a claim held by another worker")
        self._holders.pop(run_id, None)

    def claimed_run_ids(self) -> list[str]:
        return list(self._holders)

    def holder_count(self) -> int:
        return len(self._holders)

    def release_all(self) -> None:
        self._holders.clear()

    def claimed_by(self, worker_id: str) -> list[str]:
        return [rid for rid, holder in self._holders.items() if holder == worker_id]

    def is_held_by(self, run_id: str, worker_id: str) -> bool:
        return self._holders.get(run_id) == worker_id

    def claim_or_raise(self, run_id: str, worker_id: str) -> None:
        if not self.try_claim(run_id, worker_id):
            raise RuntimeError(f"run {run_id} already claimed by {self._holders.get(run_id)!r}")

    def worker_of(self, run_id: str) -> str | None:
        return self._holders.get(run_id)

    def __contains__(self, run_id: object) -> bool:
        return run_id in self._holders

    def __len__(self) -> int:
        return len(self._holders)

