from __future__ import annotations

"""Process a requires_action run: execute its tools, then submit the outputs.

A worker does two things in sequence: run the required tool calls, then submit
their outputs to advance the run. The methods are split so the realistic race is
expressible — two pollers can each execute while the run still says
``requires_action``, and only then does either submit.
"""

from assistants_models import Run, ToolOutput
from run_claim import RunClaim
from run_store import RunStore
from submission_policy import dedupe_outputs, validate_outputs_complete
from tool_executor import ToolExecutor


class RunCoordinator:
    def __init__(
        self,
        store: RunStore | None = None,
        executor: ToolExecutor | None = None,
        claim: RunClaim | None = None,
    ) -> None:
        self._store = store if store is not None else RunStore()
        self._executor = executor if executor is not None else ToolExecutor()
        self._claim = claim if claim is not None else RunClaim()

    @property
    def store(self) -> RunStore:
        return self._store

    @property
    def executor(self) -> ToolExecutor:
        return self._executor

    @property
    def world(self) -> dict:
        return self._executor.world

    def register(self, run: Run) -> Run:
        return self._store.put(run)

    def execute_required_tools(self, run_id: str) -> list[ToolOutput]:
        """Run every required tool call for a run and collect outputs."""

        run = self._store.get(run_id)
        if not run.requires_action():
            return []
        outputs: list[ToolOutput] = []
        for call in run.required_tool_calls():
            outputs.append(self._executor.execute(call))
        return outputs

    def submit(self, run_id: str, outputs: list[ToolOutput]) -> dict[str, object]:
        """Submit collected outputs and advance the run."""

        run = self._store.get(run_id)
        clean = dedupe_outputs(outputs)
        validate_outputs_complete(run, clean)
        return self._store.submit_tool_outputs(run_id, clean)

    def process_run(self, run_id: str) -> dict[str, object]:
        """Single-worker convenience: execute then submit if needed."""

        outputs = self.execute_required_tools(run_id)
        if not outputs:
            return {"run_id": run_id, "status": "noop", "applied": False}
        return self.submit(run_id, outputs)

    def process_with_worker(self, run_id: str, worker_id: str) -> dict[str, object]:
        """Process a run while holding a claim for the duration of the attempt."""

        if not self._claim.try_claim(run_id, worker_id):
            return {"run_id": run_id, "status": "busy", "applied": False}
        try:
            return self.process_run(run_id)
        finally:
            self._claim.release(run_id, worker_id)

    def pending_run_ids(self) -> list[str]:
        """Runs still waiting on tool outputs."""

        return [
            rid for rid in self._store.all_run_ids()
            if self._store.get(rid).requires_action()
        ]

    def process_all_pending(self) -> list[dict[str, object]]:
        """Drive every run currently in requires_action, once each."""

        results: list[dict[str, object]] = []
        for run_id in self.pending_run_ids():
            results.append(self.process_run(run_id))
        return results

    def outputs_for(self, run_id: str) -> list[ToolOutput]:
        return self._store.submitted_outputs(run_id)

    def status_of(self, run_id: str) -> str:
        return self._store.status_of(run_id)

    def has_double_charge(self) -> bool:
        executions = self._executor.executions
        return len(executions) != len(set(executions))

    def register_many(self, runs: list[Run]) -> None:
        for run in runs:
            self._store.put(run)

    def transition_count(self, run_id: str) -> int:
        return self._store.transition_count(run_id)

    def summary_all(self) -> dict[str, str]:
        return {rid: self._store.status_of(rid) for rid in self._store.all_run_ids()}

    def world_snapshot(self) -> dict:
        return self._executor.world_snapshot()

    def is_pending(self, run_id: str) -> bool:
        return self._store.get(run_id).requires_action()

    def claim(self) -> RunClaim:
        return self._claim

