from __future__ import annotations

"""In-memory store of runs, and the one place a run advances.

``submit_tool_outputs`` is the transition that takes a run out of
``requires_action``. It is the gate that decides whether a submission actually
changes anything. Two pollers can both reach this with outputs for the same run;
only one submission may take effect.
"""

from assistants_models import QUEUED, REQUIRES_ACTION, Run, ToolOutput


class RunStore:
    def __init__(self) -> None:
        self._runs: dict[str, Run] = {}
        self._transitions: dict[str, int] = {}

    def put(self, run: Run) -> Run:
        self._runs[run.run_id] = run
        self._transitions.setdefault(run.run_id, 0)
        return run

    def get(self, run_id: str) -> Run:
        run = self._runs.get(run_id)
        if run is None:
            raise KeyError(f"unknown run {run_id}")
        return run

    def exists(self, run_id: str) -> bool:
        return run_id in self._runs

    def status_of(self, run_id: str) -> str:
        return self.get(run_id).status

    def transition_count(self, run_id: str) -> int:
        return self._transitions.get(run_id, 0)

    def submitted_outputs(self, run_id: str) -> list[ToolOutput]:
        return list(self.get(run_id).submitted_outputs)

    def submit_tool_outputs(self, run_id: str, outputs: list[ToolOutput]) -> dict[str, object]:
        """Attach tool outputs and advance the run out of requires_action."""

        run = self.get(run_id)

        run.submitted_outputs.extend(outputs)
        run.submitted_tool_call_ids.update(o.tool_call_id for o in outputs)
        run.status = QUEUED
        self._transitions[run_id] = self._transitions.get(run_id, 0) + 1

        return {
            "run_id": run_id,
            "status": "submitted",
            "applied": True,
            "output_count": len(run.submitted_outputs),
        }

    def all_run_ids(self) -> list[str]:
        return list(self._runs)

    def runs_in_status(self, status: str) -> list[str]:
        return [rid for rid, run in self._runs.items() if run.status == status]

    def submitted_tool_call_ids(self, run_id: str) -> set[str]:
        return set(self.get(run_id).submitted_tool_call_ids)

