from __future__ import annotations

"""Idempotency ledger for tool side effects.

Each tool call carries a unique ``tool_call_id``. The ledger remembers the
output produced for an id so the same call is never run for real twice, no
matter how many workers pick up the run. It is the durable record a retry checks
before doing anything with a side effect.
"""

from assistants_models import ToolOutput


class SideEffectLedger:
    def __init__(self) -> None:
        self._outputs: dict[str, ToolOutput] = {}

    def has(self, tool_call_id: str) -> bool:
        return tool_call_id in self._outputs

    def get(self, tool_call_id: str) -> ToolOutput | None:
        return self._outputs.get(tool_call_id)

    def record(self, tool_call_id: str, output: ToolOutput) -> None:
        if not tool_call_id:
            raise ValueError("tool_call_id is required")
        self._outputs[tool_call_id] = output

    def recorded_ids(self) -> list[str]:
        return list(self._outputs)

    def size(self) -> int:
        return len(self._outputs)

    def snapshot(self) -> dict[str, str]:
        return {cid: out.output for cid, out in self._outputs.items()}

    def outputs(self) -> list[ToolOutput]:
        return list(self._outputs.values())

    def clear(self) -> None:
        self._outputs.clear()

    def __contains__(self, tool_call_id: object) -> bool:
        return tool_call_id in self._outputs

    def __len__(self) -> int:
        return len(self._outputs)

    def keys(self) -> list[str]:
        return list(self._outputs)

    def output_text(self, tool_call_id: str) -> str | None:
        output = self._outputs.get(tool_call_id)
        return output.output if output is not None else None

    def merge(self, other: "SideEffectLedger") -> None:
        """Fold another ledger in; existing entries win (already executed)."""

        for tool_call_id, output in other._outputs.items():
            self._outputs.setdefault(tool_call_id, output)

