from __future__ import annotations

"""Rules about what a valid tool-output submission looks like.

A run only advances when every required tool call has an output. This module
checks completeness and de-dupes a worker's own output list before it reaches
the store.
"""

from assistants_models import Run, ToolOutput


class IncompleteSubmissionError(ValueError):
    """Raised when a submission does not answer every required tool call."""


def output_ids(outputs: list[ToolOutput]) -> list[str]:
    return [o.tool_call_id for o in outputs]


def dedupe_outputs(outputs: list[ToolOutput]) -> list[ToolOutput]:
    """Keep the first output per tool_call_id, preserving order."""

    seen: set[str] = set()
    deduped: list[ToolOutput] = []
    for output in outputs:
        if output.tool_call_id in seen:
            continue
        seen.add(output.tool_call_id)
        deduped.append(output)
    return deduped


def validate_outputs_complete(run: Run, outputs: list[ToolOutput]) -> None:
    required = set(run.tool_call_ids())
    provided = set(output_ids(outputs))
    missing = required - provided
    if missing:
        raise IncompleteSubmissionError(f"missing tool outputs for: {sorted(missing)}")
    extra = provided - required
    if extra:
        raise IncompleteSubmissionError(f"outputs for unknown tool calls: {sorted(extra)}")


def is_complete(run: Run, outputs: list[ToolOutput]) -> bool:
    try:
        validate_outputs_complete(run, outputs)
    except IncompleteSubmissionError:
        return False
    return True


def missing_ids(run: Run, outputs: list[ToolOutput]) -> list[str]:
    return sorted(set(run.tool_call_ids()) - set(output_ids(outputs)))


def extra_ids(run: Run, outputs: list[ToolOutput]) -> list[str]:
    return sorted(set(output_ids(outputs)) - set(run.tool_call_ids()))


def distinct_output_count(outputs: list[ToolOutput]) -> int:
    return len(set(output_ids(outputs)))

