from __future__ import annotations

"""Run the real side effects behind tool calls.

Handlers mutate a shared ``world`` (a refund total, an inventory reservation
map) so re-running one is observable. Every real handler invocation is logged so
tests and invariants can prove a side effect happened exactly once.
"""

import json
from typing import Callable

from assistants_models import ToolCall, ToolOutput
from side_effect_ledger import SideEffectLedger


def _issue_refund(args: dict, world: dict) -> str:
    amount = int(args.get("amount_cents", 0))
    if amount < 0:
        raise ValueError("refund amount must be non-negative")
    world["refund_total_cents"] = world.get("refund_total_cents", 0) + amount
    return json.dumps({"refunded_cents": amount, "order_id": args.get("order_id")})


def _reserve_inventory(args: dict, world: dict) -> str:
    sku = str(args.get("sku", "")).strip()
    qty = int(args.get("qty", 0))
    if qty < 0:
        raise ValueError("reserve qty must be non-negative")
    reserved = world.setdefault("reserved", {})
    reserved[sku] = reserved.get(sku, 0) + qty
    return json.dumps({"sku": sku, "reserved": qty})


def _adjust_loyalty_points(args: dict, world: dict) -> str:
    customer = str(args.get("customer_id", "")).strip()
    delta = int(args.get("points", 0))
    points = world.setdefault("loyalty_points", {})
    points[customer] = points.get(customer, 0) + delta
    return json.dumps({"customer_id": customer, "points_delta": delta})


def default_world() -> dict:
    return {"refund_total_cents": 0, "reserved": {}, "loyalty_points": {}}


class ToolExecutor:
    def __init__(
        self,
        ledger: SideEffectLedger | None = None,
        world: dict | None = None,
    ) -> None:
        self._ledger = ledger if ledger is not None else SideEffectLedger()
        self._world = world if world is not None else default_world()
        self._handlers: dict[str, Callable[[dict, dict], str]] = {
            "issue_refund": _issue_refund,
            "reserve_inventory": _reserve_inventory,
            "adjust_loyalty_points": _adjust_loyalty_points,
        }
        self._executions: list[str] = []

    @property
    def world(self) -> dict:
        return self._world

    @property
    def ledger(self) -> SideEffectLedger:
        return self._ledger

    @property
    def executions(self) -> list[str]:
        """tool_call_ids whose side effect was actually run (not deduped)."""

        return list(self._executions)

    def real_execution_count(self) -> int:
        return len(self._executions)

    def register_handler(self, name: str, handler: Callable[[dict, dict], str]) -> None:
        self._handlers[name] = handler

    def supported_tools(self) -> list[str]:
        return sorted(self._handlers)

    def executions_for(self, tool_call_id: str) -> int:
        return self._executions.count(tool_call_id)

    def refund_total_cents(self) -> int:
        return int(self._world.get("refund_total_cents", 0))

    def reserved_units(self, sku: str) -> int:
        return int(self._world.get("reserved", {}).get(sku, 0))

    def reset_world(self) -> None:
        self._world.clear()
        self._world.update(default_world())
        self._executions.clear()

    def world_snapshot(self) -> dict:
        return {
            "refund_total_cents": self.refund_total_cents(),
            "reserved": dict(self._world.get("reserved", {})),
            "loyalty_points": dict(self._world.get("loyalty_points", {})),
        }

    def loyalty_balance(self, customer_id: str) -> int:
        return int(self._world.get("loyalty_points", {}).get(customer_id, 0))

    def _handler_for(self, name: str) -> Callable[[dict, dict], str]:
        handler = self._handlers.get(name)
        if handler is None:
            raise KeyError(f"no handler for tool {name!r}")
        return handler

    def execute(self, call: ToolCall) -> ToolOutput:
        """Execute one tool call and return its output."""

        handler = self._handler_for(call.name)
        result = handler(call.parsed_arguments(), self._world)
        output = ToolOutput(tool_call_id=call.id, output=result)
        self._executions.append(call.id)
        self._ledger.record(call.id, output)
        return output

