        return self._executions.count(tool_call_id)

    def refund_total_cents(self) -> int:
        return int(self._world.get("refund_total_cents", 0))

    def reserved_units(self, sku: str) -> int:
        return int(self._world.get("reserved", {}).get(sku, 0))

    def reset_world(self) -> None:
        self._world.clear()
        self._world.update(default_world())
        self._executions.clear()

    def world_snapshot(self) -> dict:
        return {
            "refund_total_cents": self.refund_total_cents(),
            "reserved": dict(self._world.get("reserved", {})),
            "loyalty_points": dict(self._world.get("loyalty_points", {})),
        }

    def loyalty_balance(self, customer_id: str) -> int:
        return int(self._world.get("loyalty_points", {}).get(customer_id, 0))

    def _handler_for(self, name: str) -> Callable[[dict, dict], str]:
        handler = self._handlers.get(name)
        if handler is None:
            raise KeyError(f"no handler for tool {name!r}")
        return handler

    def execute(self, call: ToolCall) -> ToolOutput:
        """Execute one tool call and return its output."""

        handler = self._handler_for(call.name)
        result = handler(call.parsed_arguments(), self._world)
        output = ToolOutput(tool_call_id=call.id, output=result)
        self._executions.append(call.id)
        self._ledger.record(call.id, output)
        return output
